<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
<style>
/* ══════════════════════════════════════════════════════════════
   ROOT TOKENS — Cartoon Casino
══════════════════════════════════════════════════════════════ */
:root {
    --felt:        #0c7a52;
    --felt-d:      #075a3c;
    --felt-l:      #0e9463;
    --wood:        #5a3417;
    --wood-d:      #3c2210;
    --gold:        #f7c948;
    --gold-d:      #c99a1f;
    --cream:       #fff6e2;
    --ink:         #1c1408;
    --red:         #e0473a;
    --red-d:       #a8321f;
    --green:       #2fb872;
    --green-d:     #1c8a54;
    --blue:        #3d8bf0;
    --purple:      #8b5cf6;

    --c0: #7c3aed; --c0d: #5a25b0;
    --c1: #0891b2; --c1d: #056a80;
    --c2: #d97706; --c2d: #a35c04;
    --c3: #0f766e; --c3d: #0a5450;
}

*,*::before,*::after { margin:0; padding:0; box-sizing:border-box; font-family:'Nunito',sans-serif; }

html,body {
    width:100%; height:100%;
    overflow:hidden;
    background: var(--felt-d);
    color: var(--cream);
    user-select:none; -webkit-user-select:none;
}

.cartoon-head { font-family:'Baloo 2',cursive; }
.deal-head    { font-family:'Fredoka',sans-serif; }

/* ══════════════════════════════════════════════════════════════
   FELT TABLE BACKGROUND
══════════════════════════════════════════════════════════════ */
#bg {
    position:fixed; inset:0; z-index:0;
    background:
        radial-gradient(ellipse at 50% 30%, var(--felt-l) 0%, var(--felt) 45%, var(--felt-d) 100%);
}
#bg::before {
    content:'';
    position:absolute; inset:0;
    background-image:
        repeating-linear-gradient(45deg, rgba(255,255,255,.025) 0 2px, transparent 2px 26px),
        repeating-linear-gradient(-45deg, rgba(0,0,0,.04) 0 2px, transparent 2px 26px);
}
/* Wood rail border */
#bg::after {
    content:'';
    position:absolute; inset:0;
    border:22px solid var(--wood);
    box-shadow:
        inset 0 0 0 6px var(--wood-d),
        inset 0 0 40px rgba(0,0,0,.5);
    pointer-events:none;
}
.suit-deco {
    position:fixed; z-index:0; opacity:.07; font-size:120px; color:#fff;
    pointer-events:none; transform:rotate(-12deg);
}

/* ══════════════════════════════════════════════════════════════
   HUD
══════════════════════════════════════════════════════════════ */
#hud {
    position:fixed; top:22px; left:22px; right:22px; z-index:100;
    display:flex; align-items:center; gap:14px;
}
.hud-logo {
    font-family:'Baloo 2',cursive; font-size:15px; font-weight:800;
    color:var(--gold); text-shadow:2px 2px 0 var(--wood-d);
    background:rgba(0,0,0,.28); border:3px solid var(--gold-d);
    border-radius:14px; padding:8px 16px; flex-shrink:0;
    display:flex; align-items:center; gap:8px;
}
#lives-row { display:flex; gap:5px; flex-shrink:0; }
.life-chip {
    width:26px; height:26px; border-radius:50%;
    background: radial-gradient(circle at 35% 30%, #ff8a7a, var(--red) 60%, var(--red-d));
    border:2px solid #fff2d8; box-shadow:0 2px 4px rgba(0,0,0,.4);
    display:flex; align-items:center; justify-content:center; font-size:11px;
    transition:.25s;
}
.life-chip.lost { background:#3a3a3a; border-color:#555; filter:grayscale(1); opacity:.35; transform:scale(.7) rotate(15deg); }
.hud-spacer { flex:1; }
.hud-chip {
    background:rgba(0,0,0,.3); border:3px solid var(--gold-d);
    border-radius:14px; padding:7px 16px; text-align:center; min-width:70px;
}
.hud-chip .val { font-family:'Baloo 2',cursive; font-size:19px; font-weight:800; color:var(--gold); display:block; line-height:1; }
.hud-chip .lbl { font-size:9px; font-weight:800; color:rgba(255,255,255,.55); text-transform:uppercase; letter-spacing:.5px; }
.hud-chip.streak { border-color:var(--red-d); display:none; }
.hud-chip.streak .val { color:#ff8a6b; }

/* ══════════════════════════════════════════════════════════════
   DEALER BANNER (question)
══════════════════════════════════════════════════════════════ */
#dealer-banner {
    position:fixed; top:78px; left:50%; transform:translateX(-50%);
    z-index:60; width:min(92vw,700px);
}
.dealer-sign {
    background: linear-gradient(180deg,#7a4a24,var(--wood) 40%, var(--wood-d));
