}

/* ══════════════════════════════════════════════════════════════
   TABLE — deck / burn pile / active card
══════════════════════════════════════════════════════════════ */
#table-area {
    position:fixed; inset:0; z-index:10;
    display:flex; align-items:center; justify-content:center;
    padding-top:60px;
}
.table-row {
    display:flex; align-items:center; justify-content:center;
    gap:clamp(14px,4vw,60px);
    width:100%;
}

/* ── Pile stacks (burn pile / remaining deck) ── */
.pile-wrap { display:flex; flex-direction:column; align-items:center; gap:8px; flex-shrink:0; }
.pile-label {
    font-family:'Baloo 2',cursive; font-size:11px; font-weight:800;
    color:rgba(255,255,255,.65); letter-spacing:.5px; text-align:center;
    background:rgba(0,0,0,.25); padding:4px 12px; border-radius:20px;
}
.pile-stack {
    position:relative; width:64px; height:88px;
}
.pile-card {
    position:absolute; inset:0;
    border-radius:10px;
    background:
        repeating-linear-gradient(45deg, var(--red) 0 6px, var(--red-d) 6px 12px);
    border:3px solid var(--cream);
    box-shadow:0 3px 6px rgba(0,0,0,.4);
}
.pile-count {
    font-family:'Baloo 2',cursive; font-weight:800; font-size:16px;
    color:var(--gold); text-shadow:1px 1px 0 #000;
}
#burn-pile .pile-card { filter:brightness(.6) saturate(.7); }
#burn-pile.danger .pile-label { color:#ff8a6b; }

/* ── Active flipping card ── */
#active-card-wrap {
    display:flex; flex-direction:column; align-items:center; gap:14px;
    flex-shrink:0;
}
.card-3d-outer { width:min(72vw,260px); height:min(72vw,260px)*1.3; perspective:1400px; }
.card-3d-outer { width:220px; height:300px; perspective:1400px; }
.card-3d {
    position:relative; width:100%; height:100%;
    transform-style:preserve-3d;
    transition:transform .5s cubic-bezier(.34,1.56,.64,1);
}
.card-3d.flipped { transform:rotateY(180deg); }
.card-face {
    position:absolute; inset:0;
    border-radius:20px;
    backface-visibility:hidden;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    border:5px solid var(--cream);
    box-shadow:0 10px 0 rgba(0,0,0,.3), 0 16px 30px rgba(0,0,0,.4);
}
.face-back {
    background:
        radial-gradient(circle at 50% 50%, var(--red) 0%, var(--red-d) 75%);
}
.face-back::before {
    content:''; position:absolute; inset:10px;
    border:3px dashed rgba(255,255,255,.4); border-radius:12px;
}
.face-back .back-icon { font-size:54px; opacity:.85; filter:drop-shadow(1px 1px 0 rgba(0,0,0,.3)); }
.face-front {
    background: linear-gradient(160deg,#fffdf5,var(--cream) 60%,#fceec2);
    transform:rotateY(180deg);
    padding:20px 18px;
}
.card-letter-badge {
    width:42px; height:42px; border-radius:12px;
    background:var(--c0); color:#fff;
    display:flex; align-items:center; justify-content:center;
    font-family:'Baloo 2',cursive; font-weight:800; font-size:19px;
    box-shadow:0 3px 0 var(--c0d);
    margin-bottom:12px;
}
.card-3d-outer[data-idx="0"] .card-letter-badge { background:var(--c0); box-shadow:0 3px 0 var(--c0d); }
.card-3d-outer[data-idx="1"] .card-letter-badge { background:var(--c1); box-shadow:0 3px 0 var(--c1d); }
.card-3d-outer[data-idx="2"] .card-letter-badge { background:var(--c2); box-shadow:0 3px 0 var(--c2d); }
.card-3d-outer[data-idx="3"] .card-letter-badge { background:var(--c3); box-shadow:0 3px 0 var(--c3d); }
#card-text {
    font-family:'Fredoka',sans-serif; font-weight:500; font-size:clamp(13px,2vw,16px);
    color:var(--ink); text-align:center; line-height:1.4;
}
.card-face.result-correct { border-color:var(--green); box-shadow:0 0 0 5px rgba(47,184,114,.35), 0 10px 0 rgba(0,0,0,.3); }
.card-face.result-wrong   { border-color:var(--red);   box-shadow:0 0 0 5px rgba(224,71,58,.35), 0 10px 0 rgba(0,0,0,.3); }

/* ── Timer ring above card ── */
#timer-wrap { position:relative; width:64px; height:64px; }
