.timer-bg { fill:none; stroke:rgba(255,255,255,.15); stroke-width:6; }
.timer-fg { fill:none; stroke:var(--gold); stroke-width:6; stroke-linecap:round; transition:stroke-dashoffset 1s linear, stroke .2s; }
.timer-fg.warn { stroke:#ff8a3d; }
.timer-fg.danger { stroke:var(--red); }
#timer-num {
    position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
    font-family:'Baloo 2',cursive; font-weight:800; font-size:22px; color:#fff;
}

/* ══════════════════════════════════════════════════════════════
   ACTION BUTTONS
══════════════════════════════════════════════════════════════ */
#action-row {
