.btn-hit:not(:disabled):hover  { transform:translateY(-2px); }
.btn-fold { background:linear-gradient(180deg,#ff6a5a,var(--red)); box-shadow:0 6px 0 var(--red-d); }
.btn-fold:not(:disabled):hover { transform:translateY(-2px); }

/* ══════════════════════════════════════════════════════════════
   BLIND FOLD WARNING FLASH
══════════════════════════════════════════════════════════════ */
#blind-flash {
    position:fixed; inset:0; z-index:250;
    background:rgba(10,4,2,.92);
    display:none; align-items:center; justify-content:center; flex-direction:column;
    text-align:center; padding:30px;
}
#blind-flash.show { display:flex; animation:blindPulse .5s ease; }
@keyframes blindPulse { 0%{opacity:0;transform:scale(.8);} 100%{opacity:1;transform:scale(1);} }
.blind-title {
    font-family:'Baloo 2',cursive; font-size:clamp(26px,6vw,46px); color:var(--red);
    text-shadow:0 0 30px rgba(224,71,58,.7); letter-spacing:2px; margin-bottom:14px;
    animation:blindShake .4s ease infinite alternate;
}
@keyframes blindShake { from{transform:rotate(-1.5deg);} to{transform:rotate(1.5deg);} }
.blind-sub { font-family:'Fredoka',sans-serif; font-size:16px; color:#ffd8c9; max-width:480px; }

/* ══════════════════════════════════════════════════════════════
   RESULT TOAST (per question)
══════════════════════════════════════════════════════════════ */
#result-toast {
    position:fixed; top:50%; left:50%; transform:translate(-50%,-50%) scale(.6);
