#result-toast.lose { background:rgba(224,71,58,.95); box-shadow:0 0 40px rgba(224,71,58,.6); }
.toast-title { font-size:26px; color:#fff; text-shadow:2px 2px 0 rgba(0,0,0,.25); }
.toast-sub   { font-family:'Fredoka',sans-serif; font-size:13px; color:#fff; opacity:.9; margin-top:4px; }

/* ══════════════════════════════════════════════════════════════
   INSTRUCTIONS SCREEN
══════════════════════════════════════════════════════════════ */
#instructions-screen {
    position:fixed; inset:0; z-index:300;
