    display:flex; gap:12px; align-items:flex-start;
}
.inst-twist .twist-icon { font-size:26px; flex-shrink:0; }
.inst-twist b { color:#ff9a86; }
.inst-start-btn {
    font-family:'Baloo 2',cursive; font-size:clamp(15px,2.6vw,19px); font-weight:800;
    letter-spacing:1px; padding:16px 40px; border:none; cursor:pointer;
    background:linear-gradient(180deg,#3fd489,var(--green)); color:#fff;
    border-radius:20px; box-shadow:0 6px 0 var(--green-d);
    transition:transform .12s;
}
.inst-start-btn:hover { transform:translateY(-3px); }
.inst-start-btn:active { transform:translateY(3px); box-shadow:0 2px 0 var(--green-d); }

/* ══════════════════════════════════════════════════════════════
   GET READY OVERLAY
══════════════════════════════════════════════════════════════ */
#overlay {
    position:fixed; inset:0; z-index:180;
    background:rgba(4,20,14,.92);
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    opacity:0; pointer-events:none; transition:opacity .25s; text-align:center; padding:30px;
}
#overlay.show { opacity:1; pointer-events:all; }
.ov-big { font-family:'Baloo 2',cursive; font-size:clamp(30px,7vw,58px); color:#fff; letter-spacing:2px; text-shadow:0 0 26px rgba(247,201,72,.5); }
.ov-sub { font-family:'Fredoka',sans-serif; font-size:14px; color:rgba(255,255,255,.5); margin-top:10px; }

/* ══════════════════════════════════════════════════════════════
   RESULT SCREEN
══════════════════════════════════════════════════════════════ */
#result-screen {
    display:none; position:fixed; inset:0; z-index:350;
    background:linear-gradient(160deg,var(--wood-d) 0%,#1c1408 55%,var(--felt-d) 100%);
    flex-direction:column; align-items:center; justify-content:center;
    text-align:center; padding:30px;
}
#result-screen.show { display:flex; }
.result-emoji { font-size:64px; margin-bottom:12px; animation:trophyBounce .6s cubic-bezier(.34,1.56,.64,1); }
@keyframes trophyBounce { from{transform:scale(0) rotate(-20deg);} to{transform:scale(1) rotate(0);} }
.result-title { font-family:'Baloo 2',cursive; font-size:clamp(22px,5vw,34px); color:var(--gold); text-shadow:3px 3px 0 var(--wood-d); margin-bottom:6px; }
.result-sub { font-family:'Fredoka',sans-serif; font-size:14px; color:rgba(255,255,255,.6); margin-bottom:22px; }
.result-stats { display:flex; gap:12px; justify-content:center; flex-wrap:wrap; margin-bottom:20px; }
.rs { background:rgba(0,0,0,.3); border:2px solid var(--gold-d); border-radius:14px; padding:14px 22px; min-width:96px; }
.rs .rv { font-family:'Baloo 2',cursive; font-size:24px; color:var(--gold); display:block; }
.rs .rl { font-size:9px; color:rgba(255,255,255,.5); font-weight:800; letter-spacing:.5px; text-transform:uppercase; }
.xp-badge {
    font-family:'Baloo 2',cursive; font-size:14px; background:rgba(247,201,72,.12);
    border:2px solid var(--gold); color:var(--gold); padding:10px 26px; border-radius:20px;
    margin-bottom:22px; animation:xpPop .45s .4s cubic-bezier(.34,1.56,.64,1) both;
}
@keyframes xpPop { from{transform:scale(.4);opacity:0;} to{transform:scale(1);opacity:1;} }
.result-btns { display:flex; gap:10px; flex-wrap:wrap; justify-content:center; }
.btn-r { padding:13px 26px; border:none; font-family:'Baloo 2',cursive; font-weight:800; font-size:14px; border-radius:16px; cursor:pointer; transition:transform .12s; }
.btn-r:hover { transform:translateY(-2px); }
.btn-gold  { background:linear-gradient(180deg,#ffe08a,var(--gold)); color:var(--wood-d); box-shadow:0 5px 0 var(--gold-d); }
.btn-ghost { background:rgba(255,255,255,.08); color:#eee; border:2px solid rgba(255,255,255,.2); }

/* ── Confetti (cards & chips) ── */
.confetti-dot { position:fixed; pointer-events:none; z-index:999; animation:confFall var(--dur,2s) var(--del,0s) ease-in forwards; }
@keyframes confFall { 0%{transform:translateY(-20px) rotate(0);opacity:1;} 100%{transform:translateY(110vh) rotate(600deg);opacity:0;} }

/* ── Responsive ── */
@media (max-width:640px) {
    .table-row { gap:10px; }
    .pile-stack { width:44px; height:62px; }
    .card-3d-outer { width:150px; height:210px; }
    #dealer-banner { top:70px; width:94vw; }
    .dealer-sign { padding:12px 16px; }
    #action-row { gap:10px; bottom:16px; }
    .btn-decision { padding:13px 22px; font-size:15px; }
    .inst-grid { grid-template-columns:1fr; }
}

/* ════════════════════════════════════════════════
   CASINO ENHANCEMENTS — neon, glow, shimmer
════════════════════════════════════════════════ */
@keyframes goldShimmer {
    0%,100%{ background-position:0% 50%; }
    50%    { background-position:100% 50%; }
}
@keyframes neonPulse {
    0%,100%{ text-shadow:0 0 8px #f7c948,0 0 20px #f7c948,0 0 40px #c99a1f,2px 2px 0 #3c2210; }
    50%    { text-shadow:0 0 16px #ffe98a,0 0 40px #f7c948,0 0 70px #c99a1f,2px 2px 0 #3c2210; }
}
@keyframes suitFloat {
    0%  { transform:rotate(-12deg) translateY(0); opacity:.07; }
    50% { transform:rotate(-8deg)  translateY(-18px); opacity:.11; }
    100%{ transform:rotate(-12deg) translateY(0); opacity:.07; }
}
@keyframes chipBounce {
    0%  { transform:translateY(0) scale(1) rotate(0deg); opacity:1; }
    40% { transform:translateY(-60px) scale(1.2) rotate(180deg); opacity:1; }
    100%{ transform:translateY(-130px) scale(.7) rotate(420deg); opacity:0; }
}
@keyframes ambientGlow {
    0%,100%{ box-shadow:inset 0 0 80px rgba(247,201,72,.04); }
    50%    { box-shadow:inset 0 0 140px rgba(247,201,72,.09); }
}
@keyframes cardShine {
    0%   { box-shadow:0 10px 0 rgba(0,0,0,.3),0 16px 30px rgba(0,0,0,.4); }
    50%  { box-shadow:0 10px 0 rgba(0,0,0,.3),0 16px 30px rgba(0,0,0,.4),0 0 24px rgba(247,201,72,.25); }
    100% { box-shadow:0 10px 0 rgba(0,0,0,.3),0 16px 30px rgba(0,0,0,.4); }
}
@keyframes blindFlash {
    0%,100%{ background:rgba(10,4,2,.92); }
    20%    { background:rgba(100,10,10,.97); }
    40%    { background:rgba(10,4,2,.94); }
}

/* Logo → Cinzel Decorative + neon */
.hud-logo {
    font-family:'Cinzel Decorative',cursive !important;
    font-size:13px !important;
    animation:neonPulse 2.4s ease-in-out infinite;
    background:rgba(0,0,0,.38) !important;
    border:3px solid #f7c948 !important;
    border-radius:14px;
    letter-spacing:1px;
}

/* Table ambient breathing glow */
#bg { animation:ambientGlow 5s ease-in-out infinite; }

/* Enhanced suit decorations */
.suit-deco { animation:suitFloat 6s ease-in-out infinite; font-size:140px !important; }
.suit-deco:nth-child(3) { animation-delay:-2s; font-size:110px !important; }
.suit-deco:nth-child(4) { animation-delay:-4s; font-size:160px !important; }
.suit-deco:nth-child(5) { animation-delay:-1s; }
.suit-deco:nth-child(6) { animation-delay:-3s; }

/* Card idle shimmer */
.card-3d-outer:not(.resolved) .card-face.face-front {
    animation:cardShine 3s ease-in-out infinite;
}

/* HIT button — gold neon glow on hover */
.btn-hit:not(:disabled):hover {
    box-shadow:0 6px 0 var(--green-d), 0 0 22px rgba(63,212,137,.55) !important;
    transform:translateY(-3px) !important;
}
/* FOLD button — red neon on hover */
.btn-fold:not(:disabled):hover {
    box-shadow:0 6px 0 var(--red-d), 0 0 22px rgba(224,71,58,.55) !important;
    transform:translateY(-3px) !important;
}

/* Dealer sign — thicker gold border + glow */
.dealer-sign {
    border:5px solid var(--wood-d) !important;
    box-shadow:0 8px 0 rgba(0,0,0,.35), 0 14px 26px rgba(0,0,0,.4), 0 0 0 3px rgba(247,201,72,.18) !important;
}

/* Timer — gold pulse when danger */
#timer-num { font-family:'Oswald',sans-serif !important; font-size:26px !important; }

/* Pile labels — casino chip style */
.pile-label {
    font-family:'Cinzel Decorative',cursive !important;
    font-size:9px !important;
    letter-spacing:1px !important;
