    /* ══════════════════════════════════════════════════════════════
     GRAPHIC UPGRADE PACK — spotlight, embers, dealer avatar, foil,
     card pips, timer halo, button ripple
    ══════════════════════════════════════════════════════════════ */

    /* Rotating stage spotlight behind the table */
    #spotlight {
      position:fixed; inset:0; z-index:1; pointer-events:none;
      background: conic-gradient(from 0deg at 50% 38%,
          rgba(255,244,200,.10) 0deg, transparent 40deg,
          transparent 320deg, rgba(255,244,200,.10) 360deg);
      animation: spotSpin 14s linear infinite;
      mix-blend-mode: screen;
    }
    @keyframes spotSpin { to { transform:rotate(360deg); } }

    /* Ambient floating embers / gold dust */
    #embers { position:fixed; inset:0; z-index:2; pointer-events:none; overflow:hidden; }
    .ember {
      position:absolute; bottom:-10px; border-radius:50%;
      background: radial-gradient(circle, #ffe9a8 0%, #f7c948 55%, transparent 75%);
      opacity:0; animation: emberRise var(--dur,6s) linear var(--del,0s) infinite;
      filter: drop-shadow(0 0 4px rgba(247,201,72,.8));
    }
    @keyframes emberRise {
      0%   { transform:translateY(0) translateX(0); opacity:0; }
      8%   { opacity:.85; }
      100% { transform:translateY(-105vh) translateX(var(--drift,20px)); opacity:0; }
    }

    /* Dealer avatar — sits above the dealer sign, reacts to game state */
    #dealer-avatar {
      position:relative; z-index:65; margin:0 auto 8px; width:74px; height:74px;
      display:flex; align-items:center; justify-content:center;
      background: radial-gradient(circle at 35% 30%, #2a2a2a, #0e0e0e 70%);
      border:4px solid var(--gold); border-radius:50%;
      box-shadow:0 6px 0 var(--gold-d), 0 10px 18px rgba(0,0,0,.5);
      animation: dealerBreathe 3.2s ease-in-out infinite;
    }
    @keyframes dealerBreathe { 0%,100%{ transform:translateY(0) scale(1);} 50%{ transform:translateY(-3px) scale(1.02);} }
    #dealer-avatar .df {
      font-size:36px; line-height:1; filter:drop-shadow(1px 2px 0 rgba(0,0,0,.4));
      transition: transform .18s ease;
    }
    #dealer-avatar.react-correct .df { animation: dealerGasp .5s ease; }
    #dealer-avatar.react-wrong   .df { animation: dealerSmirk .6s ease; }
    #dealer-avatar.react-blind   .df { animation: dealerShock .6s ease infinite alternate; }
    @keyframes dealerGasp  { 0%{transform:scale(1);} 30%{transform:scale(1.3) rotate(-6deg);} 100%{transform:scale(1);} }
    @keyframes dealerSmirk { 0%{transform:rotate(0);} 25%{transform:rotate(-8deg) scale(1.1);} 50%{transform:rotate(6deg) scale(1.1);} 100%{transform:rotate(0);} }
    @keyframes dealerShock { from{transform:scale(1) rotate(-2deg);} to{transform:scale(1.15) rotate(2deg);} }
    #dealer-avatar::after {
      content:'DEALER'; position:absolute; bottom:-11px; left:50%; transform:translateX(-50%);
      font-family:'Cinzel Decorative',cursive; font-size:7px; font-weight:700; letter-spacing:1.5px;
      background:var(--gold); color:var(--wood-d); padding:2px 8px; border-radius:10px;
      box-shadow:0 2px 0 var(--gold-d); white-space:nowrap;
    }

    /* Card corner pips — top-left / bottom-right, real-card feel */
    .card-pip {
      position:absolute; font-family:'Oswald',sans-serif; font-weight:700; font-size:13px;
      color:var(--c0d); line-height:1; text-align:center; opacity:.75;
    }
    .card-pip .pip-suit { display:block; font-size:15px; margin-top:1px; }
    .card-pip.tl { top:10px; left:10px; }
    .card-pip.br { bottom:10px; right:10px; transform:rotate(180deg); }

    /* Holographic foil sweep across a freshly-flipped card */
    .card-face.face-front::after {
      content:''; position:absolute; inset:0; border-radius:16px;
      background:linear-gradient(115deg, transparent 30%, rgba(255,255,255,.55) 48%, transparent 66%);
      background-size:250% 250%; background-position:150% 150%;
      opacity:0; pointer-events:none;
    }
    .card-face.face-front.sweep::after {
      animation: foilSweep .9s ease;
    }
    @keyframes foilSweep {
      0%   { opacity:0; background-position:150% 150%; }
      15%  { opacity:.9; }
      100% { opacity:0; background-position:-30% -30%; }
    }

    /* Timer halo — pulses harder as time runs out */
    #timer-wrap { filter: drop-shadow(0 0 0 rgba(247,201,72,0)); transition:filter .3s; }
    #timer-wrap.halo-warn   { animation: haloPulse 1s ease-in-out infinite; }
    #timer-wrap.halo-danger { animation: haloPulse .4s ease-in-out infinite; }
    @keyframes haloPulse {
      0%,100% { filter: drop-shadow(0 0 6px rgba(224,71,58,.15)); }
      50%     { filter: drop-shadow(0 0 16px rgba(224,71,58,.75)); }
    }

    /* Button ripple */
    .btn-decision { position:relative; overflow:hidden; }
    .btn-ripple {
      position:absolute; border-radius:50%; background:rgba(255,255,255,.55);
      transform:scale(0); pointer-events:none; animation: rippleGrow .55s ease-out forwards;
    }
    @keyframes rippleGrow { to { transform:scale(3.2); opacity:0; } }

    /* Gold coin variant for confetti */
    .confetti-coin {
      position:fixed; pointer-events:none; z-index:999; width:20px; height:20px; border-radius:50%;
      background:radial-gradient(circle at 35% 30%, #fff6cf, var(--gold) 55%, var(--gold-d));
      box-shadow:0 0 6px rgba(247,201,72,.7), inset 0 0 0 2px rgba(255,255,255,.5);
      animation: coinFall var(--dur,2.2s) var(--del,0s) linear forwards;
    }
    @keyframes coinFall {
      0%   { transform:translateY(-20px) rotateY(0deg); opacity:1; }
      100% { transform:translateY(112vh) rotateY(900deg); opacity:0; }
    }

    @media (max-width:640px) {
      #dealer-avatar { width:56px; height:56px; }
      #dealer-avatar .df { font-size:26px; }
    }

    /* Chip particle (spawned by JS) */
.chip-particle {
    position:fixed; pointer-events:none; z-index:999;
    font-size:28px;
    animation:chipBounce var(--dur,.9s) var(--del,0s) ease-out forwards;
}

/* Mute button */
#mute-btn {
    background:rgba(0,0,0,.3); border:3px solid rgba(247,201,72,.5);
    border-radius:50%; width:40px; height:40px;
    display:flex; align-items:center; justify-content:center;
    font-size:16px; cursor:pointer; color:var(--gold);
    transition:border-color .2s, transform .1s; flex-shrink:0;
}
#mute-btn:hover { border-color:var(--gold); transform:scale(1.1); }

/* Wood rail glow */
#bg::after {
    box-shadow:
        inset 0 0 0 6px var(--wood-d),
        inset 0 0 40px rgba(0,0,0,.5),
        0 0 60px rgba(247,201,72,.06) !important;
}

</style>
</head>
