<script>
/* ═══════════════════════════════════════════════════════════
   DATA
═══════════════════════════════════════════════════════════ */
const QUESTIONS  = <?php echo json_encode(array_values($mcq)); ?>;
const TOTAL_Q    = QUESTIONS.length;
const MAX_LIVES  = 3;
const CARD_TIME  = 5; // seconds per flipped card — the "chip-stack" timer
const SUITS      = ['♠','♦','♣','♥']; // corner-pip suits, one per card slot A..D

/* ═══════════════════════════════════════════════════════════
   STATE
═══════════════════════════════════════════════════════════ */
let qIdx        = 0;
let score       = 0;
let correct     = 0;
let lives       = MAX_LIVES;
let streak      = 0;
let quizLog     = [];
const completionToken = (window.crypto && crypto.randomUUID)
    ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
let currentQ    = null;
let cardOrder   = [];   // shuffled option texts for this question
let cardIdx     = 0;    // which card (0=A..3=D) is currently active
let burnPile    = [];   // folded option texts for this question
let timeLeft    = CARD_TIME;
let timerIv     = null;
let decided     = false;
let inputLocked = false;

/* ═══════════════════════════════════════════════════════════
   AUDIO — Rich Casino Sound Engine
═══════════════════════════════════════════════════════════ */
let _AC = null;
function getAC() {
    if (!_AC) { try { _AC = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){ return null; } }
    if (_AC.state === 'suspended') _AC.resume();
    return _AC;
}

/* ── Background Music ── */
let _bgmMuted = false;
function startBGM() {
    const bgm = document.getElementById('bgm');
    if (!bgm) return;
    bgm.volume = 0.28;
    bgm.play().catch(()=>{});
}
function toggleMute() {
    const bgm = document.getElementById('bgm');
    const btn = document.getElementById('mute-btn');
    _bgmMuted = !_bgmMuted;
    if (bgm) bgm.muted = _bgmMuted;
    if (btn) btn.textContent = _bgmMuted ? '🔇' : '🔊';
}

/* ── Chip particle burst ── */
function spawnChips(n=6) {
    const cx = window.innerWidth * 0.5, cy = window.innerHeight * 0.55;
    const symbols = ['🪙','💰','🎰','💎','🃏','⭐'];
    for (let i=0;i<n;i++) {
        const el = document.createElement('div');
        el.className='chip-particle';
        el.style.cssText=`left:${cx-30+Math.random()*60}px;top:${cy}px;--dur:${.7+Math.random()*.5}s;--del:${i*.06}s;`;
        el.textContent=symbols[Math.floor(Math.random()*symbols.length)];
        document.body.appendChild(el);
        setTimeout(()=>el.remove(),1400);
    }
}

/* ── Individual sound cues ── */

// Card flip — paper swish
function _sndFlip() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime, sr=ac.sampleRate;
    const buf=ac.createBuffer(1,Math.floor(sr*.18),sr);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const s=ac.createBufferSource();
    const bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.Q.value=1.2;
    bp.frequency.setValueAtTime(400,t); bp.frequency.exponentialRampToValueAtTime(3500,t+.13);
    const g=ac.createGain();
    s.buffer=buf; s.connect(bp); bp.connect(g); g.connect(ac.destination);
    g.gain.setValueAtTime(.38,t); g.gain.exponentialRampToValueAtTime(.001,t+.16);
    s.start(t); s.stop(t+.19);
    // click transient
    const o=ac.createOscillator(),g2=ac.createGain();
    o.type='triangle'; o.frequency.value=2400;
    g2.gain.setValueAtTime(.14,t); g2.gain.exponentialRampToValueAtTime(.001,t+.04);
    o.connect(g2); g2.connect(ac.destination); o.start(t); o.stop(t+.05);
}

// Casino chip click — plastic snap
function _sndChip() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime, sr=ac.sampleRate;
    const buf=ac.createBuffer(1,Math.floor(sr*.05),sr);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const s=ac.createBufferSource();
    const bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=2000; bp.Q.value=5;
    const g=ac.createGain();
    s.buffer=buf; s.connect(bp); bp.connect(g); g.connect(ac.destination);
    g.gain.setValueAtTime(.65,t); g.gain.exponentialRampToValueAtTime(.001,t+.04);
    s.start(t); s.stop(t+.055);
    const o=ac.createOscillator(),g2=ac.createGain();
    o.type='sine'; o.frequency.value=3400;
    g2.gain.setValueAtTime(.09,t); g2.gain.exponentialRampToValueAtTime(.001,t+.13);
    o.connect(g2); g2.connect(ac.destination); o.start(t); o.stop(t+.14);
}

// Fold / burn — whoosh down + fire crackle
function _sndFold() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime, sr=ac.sampleRate;
    // whoosh
    const o=ac.createOscillator(),g=ac.createGain();
    o.type='sawtooth';
    o.frequency.setValueAtTime(700,t); o.frequency.exponentialRampToValueAtTime(55,t+.32);
    g.gain.setValueAtTime(.22,t); g.gain.exponentialRampToValueAtTime(.001,t+.32);
    o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+.34);
    // fire crackle
    const buf=ac.createBuffer(1,Math.floor(sr*.28),sr);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*.7;
    const s=ac.createBufferSource();
    const hp=ac.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=1600;
    const g2=ac.createGain();
    s.buffer=buf; s.connect(hp); hp.connect(g2); g2.connect(ac.destination);
    g2.gain.setValueAtTime(.22,t+.06); g2.gain.exponentialRampToValueAtTime(.001,t+.26);
    s.start(t+.06); s.stop(t+.3);
}

// HIT — coin ching
function _sndHit() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime;
    const o=ac.createOscillator(),g=ac.createGain();
    o.type='sine';
    o.frequency.setValueAtTime(550,t); o.frequency.exponentialRampToValueAtTime(1900,t+.09);
    g.gain.setValueAtTime(.3,t); g.gain.exponentialRampToValueAtTime(.001,t+.24);
    o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+.26);
    const o2=ac.createOscillator(),g2=ac.createGain();
    o2.type='triangle'; o2.frequency.value=3800;
    g2.gain.setValueAtTime(.11,t+.07); g2.gain.exponentialRampToValueAtTime(.001,t+.32);
    o2.connect(g2); g2.connect(ac.destination); o2.start(t+.07); o2.stop(t+.34);
}

// WIN — slot machine jackpot arpeggio + coins
function _sndWin() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime;
    [523,659,784,988,1319].forEach((f,i)=>{
        const o=ac.createOscillator(),g=ac.createGain();
        o.type='square'; o.frequency.value=f;
        g.gain.setValueAtTime(.15,t+i*.07); g.gain.exponentialRampToValueAtTime(.001,t+i*.07+.2);
        o.connect(g); g.connect(ac.destination); o.start(t+i*.07); o.stop(t+i*.07+.22);
    });
    for(let i=0;i<6;i++) setTimeout(()=>_sndChip(),220+i*70);
}

// LOSE — bust descending + thud
function _sndLose() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime, sr=ac.sampleRate;
    const o=ac.createOscillator(),g=ac.createGain();
    o.type='sawtooth';
    o.frequency.setValueAtTime(360,t); o.frequency.exponentialRampToValueAtTime(55,t+.5);
    g.gain.setValueAtTime(.22,t); g.gain.exponentialRampToValueAtTime(.001,t+.5);
    o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+.55);
    const buf=ac.createBuffer(1,Math.floor(sr*.22),sr);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const s=ac.createBufferSource();
    const lp=ac.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=220;
    const g2=ac.createGain();
    s.buffer=buf; s.connect(lp); lp.connect(g2); g2.connect(ac.destination);
    g2.gain.setValueAtTime(.32,t); g2.gain.exponentialRampToValueAtTime(.001,t+.2);
    s.start(t); s.stop(t+.24);
}

// BLIND FOLD — cinematic tension rumble
function _sndBlind() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime, sr=ac.sampleRate;
    const o=ac.createOscillator(),g=ac.createGain();
    o.type='sawtooth'; o.frequency.value=50;
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(.3,t+.22);
    g.gain.exponentialRampToValueAtTime(.001,t+.75);
    o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+.78);
    const o2=ac.createOscillator(),g2=ac.createGain();
    o2.type='sine';
    o2.frequency.setValueAtTime(180,t+.1); o2.frequency.exponentialRampToValueAtTime(900,t+.65);
    g2.gain.setValueAtTime(.2,t+.1); g2.gain.exponentialRampToValueAtTime(.001,t+.68);
    o2.connect(g2); g2.connect(ac.destination); o2.start(t+.1); o2.stop(t+.7);
    const buf=ac.createBuffer(1,Math.floor(sr*.38),sr);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const s=ac.createBufferSource();
    const lp=ac.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=320;
    const g3=ac.createGain();
    s.buffer=buf; s.connect(lp); lp.connect(g3); g3.connect(ac.destination);
    g3.gain.setValueAtTime(.24,t); g3.gain.exponentialRampToValueAtTime(.001,t+.36);
    s.start(t); s.stop(t+.4);
}

// SHUFFLE — rapid card riffle
function _sndShuffle() {
    const ac=getAC(); if(!ac) return;
    for(let i=0;i<9;i++) {
        setTimeout(()=>{
            const t=ac.currentTime, sr=ac.sampleRate;
            const buf=ac.createBuffer(1,Math.floor(sr*.065),sr);
            const d=buf.getChannelData(0);
            for(let j=0;j<d.length;j++) d[j]=(Math.random()*2-1);
            const s=ac.createBufferSource();
            const bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=1100+i*90; bp.Q.value=1.1;
            const g=ac.createGain();
            s.buffer=buf; s.connect(bp); bp.connect(g); g.connect(ac.destination);
            g.gain.setValueAtTime(.2,t); g.gain.exponentialRampToValueAtTime(.001,t+.055);
            s.start(t); s.stop(t+.07);
        }, i*58);
    }
}

// START — triumphant fanfare
function _sndStart() {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime;
    [330,440,554,660,880].forEach((f,i)=>{
        const o=ac.createOscillator(),g=ac.createGain();
        o.type='square'; o.frequency.value=f;
        g.gain.setValueAtTime(.14,t+i*.09); g.gain.exponentialRampToValueAtTime(.001,t+i*.09+.22);
        o.connect(g); g.connect(ac.destination); o.start(t+i*.09); o.stop(t+i*.09+.24);
    });
}

// TICK
function _sndTick(warn=false) {
    const ac=getAC(); if(!ac) return;
    const t=ac.currentTime;
    const o=ac.createOscillator(),g=ac.createGain();
    o.type='square'; o.frequency.value=warn?1500:1050;
    g.gain.setValueAtTime(warn?.2:.13,t); g.gain.exponentialRampToValueAtTime(.001,t+.07);
    o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+.08);
}

/* ── Unified dispatcher (keeps old call sites working) ── */
function playSound(type) {
    if (type==='flip')     return _sndFlip();
    if (type==='tick')     return _sndTick(false);
    if (type==='tickWarn') return _sndTick(true);
    if (type==='hit')      return _sndHit();
    if (type==='fold')     return _sndFold();
    if (type==='win')      return _sndWin();
    if (type==='lose')     return _sndLose();
    if (type==='blind')    return _sndBlind();
    if (type==='shuffle')  return _sndShuffle();
    if (type==='start')    return _sndStart();
}

/* ═══════════════════════════════════════════════════════════
   GRAPHIC UPGRADE PACK — dealer reactions, embers, ripples
═══════════════════════════════════════════════════════════ */
const DEALER_FACES = {
    idle:    '🎩',
    correct: '😬',
    wrong:   '😏',
    blind:   '😈',
    win:     '🙄',
    lose:    '🤑'
};
function dealerReact(state) {
    const av = document.getElementById('dealer-avatar');
    const face = document.getElementById('dealer-face');
    if (!av || !face) return;
    av.classList.remove('react-correct','react-wrong','react-blind');
    face.textContent = DEALER_FACES[state] || DEALER_FACES.idle;
    if (state === 'correct') av.classList.add('react-correct');
    if (state === 'wrong')   av.classList.add('react-wrong');
    if (state === 'blind')   av.classList.add('react-blind');
}

let _emberIv = null;
function startEmbers() {
    const host = document.getElementById('embers');
    if (!host || _emberIv) return;
    _emberIv = setInterval(() => {
        const el = document.createElement('div');
        const size = 4 + Math.random()*6;
        el.className = 'ember';
        el.style.cssText = `left:${Math.random()*100}vw; width:${size}px; height:${size}px;
            --dur:${5+Math.random()*4}s; --del:0s; --drift:${(Math.random()*80-40).toFixed(0)}px;`;
        host.appendChild(el);
        setTimeout(() => el.remove(), 10000);
    }, 450);
}

function addRipple(e, btn) {
    const rect = btn.getBoundingClientRect();
    const r = document.createElement('span');
    const d = Math.max(rect.width, rect.height);
    r.className = 'btn-ripple';
    r.style.width = r.style.height = d + 'px';
    r.style.left = ((e.clientX ?? rect.left+rect.width/2) - rect.left - d/2) + 'px';
    r.style.top  = ((e.clientY ?? rect.top+rect.height/2)  - rect.top  - d/2) + 'px';
    btn.appendChild(r);
    setTimeout(() => r.remove(), 600);
}
document.getElementById('btn-hit')?.addEventListener('click', (e) => addRipple(e, e.currentTarget));
document.getElementById('btn-fold')?.addEventListener('click', (e) => addRipple(e, e.currentTarget));

/* ═══════════════════════════════════════════════════════════
   HUD
═══════════════════════════════════════════════════════════ */
function updateHUD() {
    document.getElementById('hud-score').innerText = score;
    for (let i=0;i<MAX_LIVES;i++) {
        document.getElementById(`h${i}`).className = 'life-chip' + (i>=lives?' lost':'');
    }
    const sc = document.getElementById('streak-chip');
    if (streak >= 2) { sc.style.display='block'; document.getElementById('hud-streak').innerText = streak; }
    else sc.style.display='none';
}

/* ═══════════════════════════════════════════════════════════
   START / GET READY
═══════════════════════════════════════════════════════════ */
document.getElementById('inst-start-btn').addEventListener('click', () => {
    getAC(); startBGM(); startEmbers();
    document.getElementById('instructions-screen').style.display = 'none';
    playSound('shuffle');
    const overlay = document.getElementById('overlay');
    overlay.classList.add('show');
    document.getElementById('ov-text').innerText = 'SHUFFLING...';
    setTimeout(() => {
        document.getElementById('ov-text').innerText = 'DEAL!';
        playSound('start');
        setTimeout(() => { overlay.classList.remove('show'); showQuestion(0); }, 550);
    }, 700);
});

/* ═══════════════════════════════════════════════════════════
   QUESTION FLOW
═══════════════════════════════════════════════════════════ */
function showQuestion(idx) {
    if (idx >= TOTAL_Q) { finishGame(); return; }
    currentQ  = QUESTIONS[idx];
    cardOrder = (currentQ.options || []).slice(0, 4);
    cardIdx   = 0;
    burnPile  = [];
    inputLocked = false;

    document.getElementById('q-text').innerText   = currentQ.question || '(no question text)';
    document.getElementById('q-counter').innerText = `Hand ${idx+1} of ${TOTAL_Q}`;
    document.getElementById('burn-count').innerText = '0';
    document.getElementById('burn-pile').classList.remove('danger');
    document.getElementById('deck-count').innerText = cardOrder.length;

    flipCard(0);
}

function letterFor(i) { return ['A','B','C','D'][i] || '?'; }

function flipCard(i) {
    cardIdx  = i;
    decided  = false;
    inputLocked = false;

    const outer = document.getElementById('card-outer');
    const inner = document.getElementById('card-3d');
    outer.dataset.idx = i;
    inner.classList.remove('flipped');

    document.getElementById('deck-count').innerText = Math.max(0, cardOrder.length - i);

    // brief pause showing card-back, then flip to reveal
    setTimeout(() => {
        playSound('flip');
        const letter = letterFor(i);
        const suit   = SUITS[i % SUITS.length];
        document.getElementById('card-letter').innerText = letter;
        document.getElementById('card-text').innerText   = cardOrder[i] || '...';
        document.getElementById('pip-letter-tl').innerText = letter;
        document.getElementById('pip-letter-br').innerText = letter;
        document.getElementById('pip-suit-tl').innerText   = suit;
        document.getElementById('pip-suit-br').innerText   = suit;
        const front = document.getElementById('card-front');
        front.classList.remove('result-correct','result-wrong');
        inner.classList.add('flipped');
        setButtonsEnabled(true);
        startTimer();
        // holographic foil sweep on reveal
        front.classList.remove('sweep');
        void front.offsetWidth; // restart animation
        front.classList.add('sweep');
        dealerReact('idle');
    }, 420);
}

function setButtonsEnabled(on) {
    document.getElementById('btn-hit').disabled  = !on;
    document.getElementById('btn-fold').disabled = !on;
}

/* ═══════════════════════════════════════════════════════════
   TIMER — the "chip stack" countdown
═══════════════════════════════════════════════════════════ */
function startTimer() {
    clearInterval(timerIv);
    timeLeft = CARD_TIME;
    renderTimer();
    timerIv = setInterval(() => {
        timeLeft--;
        if (timeLeft > 0) playSound(timeLeft <= 1 ? 'tickWarn' : 'tick');
        renderTimer();
        if (timeLeft <= 0) {
            clearInterval(timerIv);
            if (!decided) { decided = true; setButtonsEnabled(false); autoFold(); }
        }
    }, 1000);
}
function renderTimer() {
    const ring = document.getElementById('timer-ring');
    const wrap = document.getElementById('timer-wrap');
    const circ = 163;
    const pct  = Math.max(0, timeLeft / CARD_TIME);
    ring.style.strokeDashoffset = circ * (1 - pct);
    ring.className = 'timer-fg' + (timeLeft <= 1 ? ' danger' : timeLeft <= 2 ? ' warn' : '');
    wrap.classList.toggle('halo-danger', timeLeft <= 1);
    wrap.classList.toggle('halo-warn', timeLeft === 2);
    document.getElementById('timer-num').innerText = Math.max(0, timeLeft);
}

/* ═══════════════════════════════════════════════════════════
   DECISIONS
═══════════════════════════════════════════════════════════ */
function onHit() {
    if (decided || inputLocked) return;
    decided = true; inputLocked = true;
    clearInterval(timerIv);
    setButtonsEnabled(false);
    playSound('hit'); setTimeout(_sndChip,120);
    const finalText = cardOrder[cardIdx];
    evaluate(finalText, false, false);
}

function onFold() {
    if (decided || inputLocked) return;
    decided = true; inputLocked = true;
    clearInterval(timerIv);
    setButtonsEnabled(false);
    playSound('fold');
    doFold();
}

function autoFold() {
    inputLocked = true;
    playSound('fold');
    doFold();
}

function doFold() {
    burnPile.push(cardOrder[cardIdx]);
    document.getElementById('burn-count').innerText = burnPile.length;
    if (burnPile.length >= 3) document.getElementById('burn-pile').classList.add('danger');

    if (cardIdx >= cardOrder.length - 1) {
        // Folded the LAST card → THE BLIND FOLD
        triggerBlindFold();
    } else {
        setTimeout(() => flipCard(cardIdx + 1), 350);
    }
}

function triggerBlindFold() {
    playSound('blind');
    dealerReact('blind');
    const flash = document.getElementById('blind-flash');
    flash.classList.add('show');
    setTimeout(() => {
        flash.classList.remove('show');
        const drawn = burnPile[Math.floor(Math.random() * burnPile.length)];
        evaluate(drawn, false, true);
    }, 1800);
}

/* ═══════════════════════════════════════════════════════════
   EVALUATE FINAL ANSWER
═══════════════════════════════════════════════════════════ */
function evaluate(finalText, fromTimeout, isBlindDraw) {
    const isCorrect = (finalText || '').trim() === (currentQ.answer || '').trim();

    quizLog.push({
        q: currentQ.question,
        type: 'multiple_choice',
        options: currentQ.options || [],
        correct_answer: currentQ.answer,
        user_answer: finalText,
        is_correct: isCorrect
    });

    // Flash the active card red/green
    document.getElementById('card-front').classList.add(isCorrect ? 'result-correct' : 'result-wrong');
    dealerReact(isCorrect ? 'correct' : 'wrong');

    let pts = 0;
    if (isCorrect) {
        correct++; streak++;
        const speedBonus = isBlindDraw ? 0 : Math.round((Math.max(0,timeLeft) / CARD_TIME) * 300);
        pts = isBlindDraw ? 200 : (500 + speedBonus);
        score += pts;
        playSound('win'); spawnChips(8);
        showToast(true, isBlindDraw ? `Lucky blind draw! +${pts} pts` : `+${pts} pts`);
    } else {
        streak = 0;
        lives--;
        playSound('lose');
        showToast(false, isBlindDraw ? `Blind draw busted — it was: "${currentQ.answer}"` : `Answer was: "${currentQ.answer}"`);
    }
    updateHUD();

    setTimeout(() => {
        if (lives <= 0) { finishGame(); return; }
        qIdx++;
        showQuestion(qIdx);
    }, 1700);
}

function showToast(win, sub) {
    const t = document.getElementById('result-toast');
    t.className = 'show ' + (win ? 'win' : 'lose');
    document.getElementById('toast-title').innerText = win ? (Math.random()<0.5?'HIT! 🎉':'WINNER! 🎉') : 'BUST! 💥';
    document.getElementById('toast-sub').innerText = sub;
    setTimeout(() => { t.className = ''; }, 1400);
}

/* ═══════════════════════════════════════════════════════════
   FINISH
═══════════════════════════════════════════════════════════ */
function finishGame() {
    clearInterval(timerIv);
    const played   = qIdx + 1 <= TOTAL_Q ? Math.min(qIdx + (decided?1:0), TOTAL_Q) : TOTAL_Q;
    const totalSeen = quizLog.length || 1;
    const acc = Math.round((correct / totalSeen) * 100);

    dealerReact(lives <= 0 ? 'win' : (acc >= 50 ? 'lose' : 'win'));
    document.getElementById('res-title').innerText = lives <= 0 ? 'TABLE CLOSED — BUSTED!' : 'TABLE CLOSED!';
    document.getElementById('res-sub').innerText   = `${correct} of ${totalSeen} hands won.`;
    document.getElementById('res-score').innerText   = score;
    document.getElementById('res-correct').innerText = correct;
    document.getElementById('res-acc').innerText      = acc + '%';

    window.gameResultSavePromise = fetch('save_quiz_result.php', {
        method:  'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body:    `score=${score}&correct_answers=${correct}&total_questions=${totalSeen}&quiz_log=${encodeURIComponent(JSON.stringify(quizLog))}&completion_token=${encodeURIComponent(completionToken)}`
    })
    .then(r => r.json())
    .then(d => {
        if (d.success) {
            const badge = document.getElementById('xp-badge');
            if (badge) {
                badge.innerText = d.xp_earned > 0 ? `+${d.xp_earned} XP EARNED!` : (d.xp_message || 'No quiz XP awarded.');
                badge.style.display = 'inline-block';
            }
        }
    })
    .catch(() => {});

    setTimeout(() => {
        document.getElementById('result-screen').classList.add('show');
        if (acc >= 50) spawnConfetti();
    }, 400);
}

/* ═══════════════════════════════════════════════════════════
   CONFETTI
═══════════════════════════════════════════════════════════ */
function spawnConfetti() {
    const symbols = ['🂡','🂱','🃁','🃑','💰','⭐'];
    for (let i=0;i<50;i++) {
        const el = document.createElement('div');
        el.className = 'confetti-dot';
        el.style.cssText = `
            left:${Math.random()*100}vw; top:-20px; font-size:${16+Math.random()*10}px;
            --dur:${1.6+Math.random()*1.6}s; --del:${Math.random()*.8}s;
        `;
        el.innerText = symbols[Math.floor(Math.random()*symbols.length)];
        document.body.appendChild(el);
        setTimeout(() => el.remove(), 3400);
    }
    // gold coin shower — spinning 3D coins mixed in with the card confetti
    for (let i=0;i<24;i++) {
        const c = document.createElement('div');
        c.className = 'confetti-coin';
        c.style.cssText = `
            left:${Math.random()*100}vw; top:-20px;
            --dur:${1.8+Math.random()*1.4}s; --del:${Math.random()*.9}s;
        `;
        document.body.appendChild(c);
        setTimeout(() => c.remove(), 3600);
    }
}
</script>
<script src="retake_current_game.js"></script>
</body>
</html>